-- Official SAT Practice Tests (paper versions), generated by supabase/content/sat/build_sat.py. Do not edit by hand.
-- Run after migration 20261121000001_student_produced_responses.sql. Safe to re-run: existing exams are skipped.

select s.id, 'topic', v.name, v.ord from (values
  ('sat-math', 'Algebra', 1),
  ('sat-math', 'Advanced Math', 2),
  ('sat-math', 'Problem-Solving and Data Analysis', 3),
  ('sat-math', 'Geometry and Trigonometry', 4),
  ('sat-english', 'Craft and Structure', 1),
  ('sat-english', 'Information and Ideas', 2),
  ('sat-english', 'Standard English Conventions', 3),
  ('sat-english', 'Expression of Ideas', 4)
) as v(code, name, ord) join public.subjects s on s.code = v.code
on conflict (subject_id, kind, name) do nothing;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 7: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-7-reading-and-writing') then
    raise notice 'skipping sat-practice-test-7-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-7-reading-and-writing', 'SAT Practice Test 7: Reading and Writing', 'Official SAT Practice Test 7 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 214, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [210, 250], [220, 260], [220, 270], [220, 280], [230, 290], [230, 300], [240, 310], [240, 320], [250, 330], [270, 330], [300, 340], [310, 350], [320, 360], [320, 360], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [370, 410], [380, 420], [390, 430], [400, 440], [410, 450], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [560, 620], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 700], [670, 710], [680, 720], [690, 730], [710, 750], [720, 760], [730, 770], [750, 770], [760, 780], [770, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of a prediction about a kilonova. In this context, a “theory” is an explanation that is considered scientifically acceptable. The text states that astronomers predicted in the 1990s that a collision between a black hole and a neutron star or between two neutron stars could release a massive gamma ray burst called a kilonova, explaining that they determined this possibility based on their extensive work with existing data and simulations (“calculations and models”). In other words, the prediction was a theory—a well-supported explanation—that, as the text indicates, was later confirmed with observations in 2017."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that it is the prediction made by astronomers in the 1990s that was confirmed in 2017, and a prediction of an event isn’t “evidence,” or proof, of that event’s existence, even when the prediction is based on extensive study. Further, there would be no need for later confirmation of something that was already recognized as evidence. Choice C is incorrect because in this context, a “constant” is a situation or factor that doesn’t change. The text indicates that it is the prediction made by astronomers in the 1990s that was confirmed in 2017, and there is no reason to describe the prediction as a constant because the text doesn’t suggest that the prediction was completely unchanged over time—it addresses only the making of the prediction and its later confirmation. Choice D is incorrect because the text indicates that it is the prediction made by astronomers in the 1990s that was confirmed in 2017; although a prediction might be informed by an “experiment,” or a controlled test, a prediction is an idea rather than a test."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “clear” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because as used in the text, “clear” most nearly means transparent, or see-through. Muir states that the water beneath the boat “was so clear that it was almost invisible,” suggesting that those on the boat were able to see through the water and easily observe plants and fish below the surface."}, {"type": "paragraph", "text": "Choice A is incorrect. In some contexts “clear” can mean “simple,” or uncomplicated, but Muir is describing the water, and water isn’t typically described as either simple or complicated. Muir emphasizes the water’s transparency, not its simplicity. Choice B is incorrect. In some contexts “clear” can mean “understandable,” or reasonable or easily comprehended, but Muir is describing the water, and it doesn’t make much sense to describe water as understandable. Muir emphasizes the water’s transparency, not how easily the water can be understood. Choice C is incorrect. Although “clear” can mean “obvious,” or easily seen or understood, in some contexts, Muir’s description emphasizes that the water “was almost invisible” and that the boat seemed to be “sustained in the air,” suggesting that the water was almost impossible to see, not that it was obvious."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of how Maggie Lena Walker addressed the lack of financial services available to Black residents in Richmond, Virginia, at the turn of the twentieth century. In this context, “rectify” means to correct or remedy something undesirable. The text indicates that by chartering the St. Luke Penny Savings Bank in 1903, Walker took action to provide local Black residents with greater access to financial services like home loans and savings opportunities. This context supports the idea that she aimed to rectify the undesirable situation affecting these residents."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “prolong” would mean to lengthen something in time. The text indicates that at the turn of the twentieth century, Black residents in Richmond, Virginia, were faced with a lack of formal banking options. The text then states that Walker founded a new bank that provided these residents with financial services. Therefore, instead of prolonging the situation, she took steps to rectify, or correct, it. Choice C is incorrect because in this context, “retain” would mean to continue to have or to keep something. According to the text, at the turn of the twentieth century, Black residents in Richmond, Virginia, had few formal banking options, and Walker chartered a new institution to provide these residents with expanded financial services; therefore, she took steps to rectify, not retain, the situation. Choice D is incorrect because in this context, “highlight” would mean to emphasize or call attention to something, but the text indicates that Walker took concrete steps beyond merely drawing attention to the situation Black residents were facing in Richmond, Virginia, at the turn of the twentieth century. According to the text, Walker worked to rectify, or correct, the lack of formal banking options that were available to these residents by establishing a bank that provided them with home loans and savings opportunities."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of a relationship between the results of randomized clinical tests of how effective common medical interventions are and the conclusions practitioners reach about such interventions in real-world settings. In this context, “corroborate” means confirm or support with evidence. The text indicates that one possible explanation for the relationship being discussed is that practitioners may overlook confounding variables—that is, additional factors other than the medical interventions being investigated that affect the observed outcomes. This means that practitioners may assume that an outcome is the direct result of a medical intervention when it is actually the result of a combination of factors. Clinical trials take steps to rule out factors other than the one being studied, so if those extra factors are actually having an effect on real-world outcomes, the trials are likely to produce conclusions different from those practitioners reach in their real-world observations. In other words, clinical trials may fail to corroborate practitioners’ conclusions."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense to say that the results of clinical trials could “circumvent,” or find a way around or bypass, conclusions practitioners reach in real-world scenarios with patients; it’s possible that researchers conducting the trials might avoid engaging with practitioners’ conclusions, but findings from a study can’t choose to get around something."}, {"type": "paragraph", "text": "Choice C is incorrect because it wouldn’t make sense to say that the results of clinical trials could “disseminate,” or spread widely, conclusions practitioners reach in real-world scenarios with patients; the researchers conducting the trials might choose to draw attention to practitioners’ conclusions, but findings from a study can’t spread anything. Choice D is incorrect because it wouldn’t make sense to say that the results of clinical trials could “implement,” or put into effect, conclusions practitioners reach in real-world scenarios with patients; the researchers conducting the trials might consider practitioners’ conclusions, but findings from a study can’t put anything into effect."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of diadromous fish. In this context, “demarcated from” means separate or set apart from. The text indicates that diadromous fish differ from euryhaline fish in that diadromous fish “migrate between freshwater and marine biomes during their life,” whereas euryhaline fish do not relocate to a different biome because they can tolerate higher salinity environments. Therefore, this context suggests that because of differences between their migration patterns, diadromous fish are distinct and can be demarcated from euryhaline fish."}, {"type": "paragraph", "text": "Choice B is incorrect. Although the text states that diadromous fish migrate and relocate, the text does not suggest that diadromous fish would be “reconstituted as,” or formed again as, anything new. Only their environments change and not the fish themselves. Choice C is incorrect because the text does not suggest that diadromous fish can be “conflated with,” or combined with, euryhaline fish. Instead, the text distinguishes the two types of fish by pointing out their differences with regard to migration and tolerance for salinity. Choice D is incorrect because the text indicates that based on migration habits and tolerance for salinity, diadromous fish are different from euryhaline fish; so it would not make logical sense to say that diadromous fish would be “derived from,” or be an extension of or result from, euryhaline fish."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first two sentences of the text establish that in California, houses were heated by building fires year-round. The underlined portion then indicates that the fires didn’t merely provide physical warmth: they also represented being “home” and feeling protected. The underlined portion thus illustrates that a fire provides comfort beyond physical warmth."}, {"type": "paragraph", "text": "Choice B is incorrect because the underlined portion doesn’t summarize information that came before it. Whereas the previous two sentences describe fires’ ability to provide physical warmth to homes, the underlined portion focuses on the psychological comfort the fires offered. Choice C is incorrect. Although the text’s second sentence mentions that fires were built in the summer because fog came in, which may have cooled the house, this detail isn’t the focus of the underlined portion. Instead, the underlined portion indicates that fires were built for reasons beyond physical warmth: to create a sense of being home and safe."}, {"type": "paragraph", "text": "Choice D is incorrect because the underlined portion focuses on the emotional significance the author places on having a fire going inside the home. There is no indication that the author feels equally comfortable without a fire present."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the function of the underlined portion of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined phrase functions in the text as a whole. The text states that the wax produced by Liu and colleagues’ reactor can be turned into a surfactant. The underlined phrase, which is set off with parentheses, then provides a definition for the term “surfactant,” explaining that it’s a chemical compound that can be used as a detergent. Thus, the underlined portion of the text functions to clarify the meaning of a scientific term."}, {"type": "paragraph", "text": "Choice B is incorrect. Though the text as a whole focuses broadly on an environmental concern, the underlined phrase does not; it simply indicates what a surfactant is. Choice C is incorrect. Though the text as a whole focuses on a scientific discovery (Liu and colleagues’ solution to the problem of plastic recycling), the underlined phrase does not explain its significance; it simply defines a scientific term used in the discussion. Choice D is incorrect. Though the text as a whole includes discussion of the result found by Liu and colleagues, the underlined phrase does not discuss it; it simply defines a scientific term used in the discussion. Additionally, at no point in the text is it mentioned that the team was confused."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it best describes the function of the underlined portion in the text as a whole. In the text, the speaker mentions the occurrence in nature of seedpods being shaken by a slight wind. The speaker then goes on to compare the black seeds to thoughts, using language that indicates that the speaker’s state of mind is unsettled (e.g., “my thoughts are spent”; “My thoughts tear me, I dread their fever”). The text concludes with a comparison between the speaker’s “scattered” state of mind and the “hot shrivelled seeds.” Thus, the underlined portion of the text presents an observation of an occurrence in the natural world that the speaker then expands on to convey a sense of a turbulent interior state."}, {"type": "paragraph", "text": "Choice A is incorrect because the text does not indicate that the seedpods are the cause of the speaker’s state of mind; thus, they could not be responsible for any misgivings the speaker has. Choice B is incorrect because the text does not contrast the natural landscape with the speaker’s state of mind or describe the wind shaking the seedpods as consistent; rather, the text suggests that the state of the natural world and the speaker’s state of mind are similar in that both are unsettled. Choice D is incorrect because there is no indication in the text that the speaker regularly engages in critical self-evaluation, only that in this particular instance the speaker’s state of mind is turbulent."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first sentence of the text introduces literary scholar Jeremy Douglass’s warning to technology investors and enthusiasts against predicting the displacement of conventional books by newer media forms. The next sentence, which is underlined in part, presents Douglass’s observation that interactive texts are hardly new; they have been available for longer than technologists assume, beginning with the first time readers wrote notes in texts’ margins. Thus, the function of the underlined portion is to challenge the stance of the technology investors and enthusiasts mentioned earlier in the text. As the remainder of the text points out, newer media doesn’t necessarily replace older media, but rather, as Douglass believes, leads to new forms of expression."}, {"type": "paragraph", "text": "Choice B is incorrect because the underlined portion challenges the position taken by investors and enthusiasts; it doesn’t provide context for their claims."}, {"type": "paragraph", "text": "Choice C is incorrect because the underlined portion doesn’t mention academics or compare them to investors regarding their ability to see potential in using contemporary interactive texts; instead, the underlined portion challenges the position of investors and enthusiasts who predict that conventional books will be replaced by newer forms of media. Choice D is incorrect because the underlined portion doesn’t address technological challenges; instead, it disputes the stance taken by investors and enthusiasts, suggesting that conventional books haven’t been displaced by traditional interactions with texts, such as writing in the margins, and won’t be supplanted by newer forms of media either."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which statement about M. robustus and the Octopus Garden is best supported by the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the M. robustus population at the Octopus Garden. The text states that the scientists concluded that the site is likely used only for reproduction because over three years they saw many adults, freshly hatched octopuses, and eggs but didn’t see any juveniles. This suggests that the M. robustus octopuses that hatch at the Octopus Garden leave the site when they reach an intermediary state of development, returning only as adults for reproductive purposes."}, {"type": "paragraph", "text": "Choice B is incorrect because the text never discusses the stability of the M. robustus population at the site, only that the scientists observed 6,000 adults, hatchlings, and eggs there. Further, the text presents the site’s temperatures as likely beneficial. Choice C is incorrect because the text doesn’t provide any details about the eggs at the site and makes no mention of nests; it indicates only that eggs are present along with hatchlings and adults. Choice D is incorrect because the text makes no mention of the hatchlings feeding at the Octopus Garden, indicating only that the temperatures at the site are probably beneficial and that the site is likely used for reproduction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "What does the text most strongly suggest about the story of Hans Castorp?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a statement about Hans Castorp’s story that is suggested by the text. The narrator of the text indicates that the story about Hans Castorp will be told not because there is something particularly notable about him, since he is pleasant but “perfectly ordinary,” but because the story itself is remarkable (“very much worth telling”). The narrator then notes that there is a benefit in being at the heart of the story—that it is “in Hans Castorp’s favor” that the story is his, and maybe uniquely so (“not every story happens to everybody”). Thus, the text suggests both that the story that will be told is a remarkable one that happened to an unremarkable person and that it is reasonable to argue that the person at the center of a valuable story takes on some of the story’s value."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the narrator of the text makes the point that “not every story happens to everybody,” the narrator doesn’t state that stories are interesting simply because the people they are about are unique. Rather, the narrator suggests that one particular story is “very much worth telling” on its own and that Hans Castorp benefits from the fact that the story is remarkable and may be unique to him. Further, the narrator never suggests that the story will be hard to understand even though it is old. Choice B is incorrect. Although the narrator of the text suggests that Hans Castorp is of no particular importance, since he is a “perfectly ordinary” person, the narrator never reveals what makes the story of Castorp important, just that “the story itself” is “very much worth telling.” The narrator states that the story “took place long ago,” is “covered with the patina of history,” and can be told only “with verbs whose tense is that of the deepest past,” but the story’s age and the way it must be told aren’t presented as reasons the story is important; the narrator is simply providing details about how the story will be told. Choice C is incorrect because the narrator of the text doesn’t suggest that all stories about people who are “perfectly ordinary” (like Hans Castorp) must be told in particular ways to make it clear why those stories are consequential. Further, the narrator suggests that Hans Castorp’s story must be told “with verbs whose tense is that of the deepest past” because it took place so long ago, not because telling it that way will convey the story’s importance."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the graph, about what percentage of participants mentioned costs in the interviews?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it states the percentage of participants who mentioned costs in the interviews conducted by Judith Hilton and her team. The text states that Hilton and her team interviewed participants about factors that would encourage them to switch from single-use plastic containers to reusable containers. The graph presents three factors mentioned in the interviews (convenience, costs, and established behaviors) and the percentage of participants who mentioned each one. The graph shows that about 50% of participants mentioned costs as a factor."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph shows that about 50% of participants, not 10%, mentioned costs as a factor. Choice B is incorrect because the graph shows that about 50% of participants, not 95%, mentioned costs as a factor."}, {"type": "paragraph", "text": "Choice C is incorrect because the graph shows that about 50% of participants, not 25%, mentioned costs as a factor."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from a philosopher’s analysis of The Politics would best support the student’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the quotation that best supports the student’s claim that in The Politics, Aristotle gives advice on preserving constitutions—preventing governments from falling and maintaining order—and specifically asserts that in a healthy state, laws must be followed as strictly as possible and infractions should not be overlooked even if they are minor. The philosopher states that when Aristotle builds his argument about the characteristics of a well-functioning government, Aristotle asserts that transgression, or violation of law, will ruin the state if it “creeps in unperceived,” or goes unnoticed. The philosopher then adds that Aristotle illustrates this point by comparing the situation to one in which small but frequent expenses diminish a fortune almost unnoticeably until, eventually, the fortune is entirely gone. In other words, the philosopher indicates that Aristotle makes the point that total obedience to law preserves a healthy state while even small violations, if ignored, will undermine the health of the state."}, {"type": "paragraph", "text": "Choice B is incorrect because the philosopher addresses Aristotle’s observation about corruption within the government (in particular, preventing the possibility that members of the government can take bribes), and although corruption can involve infractions, the observation is about a subset of people within the state and isn’t directly connected to the importance of upholding total obedience to the law throughout the state. Choice C is incorrect because the philosopher discusses Aristotle’s point about those who would intentionally destroy a constitution altogether and the need for rulers to remind the populace that it would be dangerous for a constitution to collapse, but neither idea is directly connected to the importance of upholding total obedience to the law. Choice D is incorrect because the philosopher explains that Aristotle makes the point that oligarchic leaders may retain power by having members of disenfranchised classes participate in government alongside governing classes, and this point doesn’t address the importance of ensuring obedience to the law and addressing even minor violations."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding from the study, if true, would most directly support the researchers’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a finding that, if true, would most directly support the researchers’ conclusion that an observable pattern in time references in novels reflects a shift in human behavior prompted by the spread of electric lighting in the late nineteenth century. If novels published after 1880 contain significantly more references to activities occurring after 10 p.m. than novels from earlier periods do, this would suggest a change in human behavior and daily routines enabled by the availability of electric lighting. Before electric lighting—which provided illumination more easily than other available forms of light—many activities ceased after nightfall, so references to late-night activities would be less common in earlier novels. An increase in such references after 1880 would align with the researchers’ conclusion, reflecting an increase in late-night activities made possible by electric lighting."}, {"type": "paragraph", "text": "Choice A is incorrect because a decrease in references to 10 a.m. after the year 1800 would not support the researchers’ conclusion involving a shift in human behavior prompted by the spread of electric lighting toward the end of the 1800s. The time of 10 a.m. is in the morning and, in most places, characterized by daylight, so a change in references to that time would not be clearly linked to the impact of electric lighting. Choice C is incorrect because while an increase in implied time references relative to clock phrases in nineteenth-century novels could suggest a change in writing style or conventions, it does not directly support the conclusion involving a shift in human behavior prompted by the spread of electric lighting. The text indicates that the researchers’ conclusion is based on the content of the time references themselves, not the phrasing used."}, {"type": "paragraph", "text": "Choice D is incorrect. If references to noon and midnight are used with roughly the same frequency in all the novels analyzed by the researchers, this would reflect a lack of change in human behavior with regard to time and therefore would not support the researchers’ conclusion involving a shift in human behavior that occurred in response to the spread of electric lighting."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the graph to complete the statement about Mahtta et al.’s proposal regarding factors that affect urban land expansion (ULE). According to the text, ULE is influenced by urban population growth and by gross domestic product (GDP) growth per capita. Reasoning that efficient national governments provide urban services and infrastructure needed to attract economic investment, Mahtta et al. suggest that, as governments become more efficient at providing urban services and infrastructure, GDP growth per capita will account for more ULE and urban population growth will account for less. But according to the graph, Region 1 saw an increase in the percentage attributed to urban population growth from 1970– 2000 (between 60 and 65%) to 2000–2014 (between 70 and 75%) and a decrease in the percentage attributed to GDP growth per capita from 1970–2000 (between 35 and 40%) to 2000–2014 (about 25%). Because the percentage attributed to GDP growth per capita decreased (the opposite of what Mahtta et al. claimed would happen if the governments had become more efficient), the data suggest that the governments of Region 1 became less efficient at providing urban services and infrastructure over that period."}, {"type": "paragraph", "text": "Choice B is incorrect. Neither the graph nor the text gives the regions’ relative levels of economic growth or what effect Mahtta et al. would expect such growth to have. Furthermore, Mahtta et al.’s proposal suggests that Region 1’s decline in the percentage of ULE attributed to GDP growth per capita from 1970–2000 (between 35 and 40%) to 2000–2014 (about 25%) would suggest decreasing, not increasing, government efficiency over this time. Choice C is incorrect. Neither the text nor the graph provides information about the relative efficiencies of different governments in Region 2. Choice D is incorrect. Mahtta et al.’s proposal suggests that more efficient governments will have a higher percentage of their ULE driven by GDP growth per capita and a lower percentage driven by urban population growth. For Region 2, the percentage of ULE attributed to GDP growth per capita increased from 1970–2000 (between 10 and 15%) to 2000–2014 (between 45 and 50%), but the opposite is true for Region 1, which saw the percentage of ULE attributed to GDP growth per capita decline over the same period. Thus, whereas the data suggest governments in Region 2 became more efficient, the data for Region 1 suggest that those governments became less efficient, not more."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the graph that support the student’s assertion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it describes data from the graph that best support the student’s assertion that initial efforts at trade liberalization in China were shaped by firms having limited capital (assets available for use) and that this situation resolved during the 2000s. The text explains that an approach to trade liberalization involves engaging in processing imports, one type of which doesn’t require payment to a trade partner (processing with assembly) and one type of which requires upfront payment to a trade partner for raw materials (processing with inputs). The graph, which presents China’s imports for ordinary imports and both types of processing imports in the years 2000, 2003, and 2006, shows that while processing imports with assembly rose from about 250 hundred million dollars in 2000 to about 750 hundred million dollars in 2006, processing imports with inputs rose much more sharply, increasing from approximately 650 hundred million dollars in 2000 to about 2,300 hundred million dollars in 2006. Because processing with inputs requires firms to pay for materials (expending capital) and processing with assembly doesn’t, the sharper rise in processing imports with inputs suggests that Chinese firms’ assets—and thus their ability to engage in that type of processing imports—were relatively limited in (and before) 2000 and then substantially increased from 2000 to 2006. In other words, the data suggest that the situation of having limited capital resolved during the 2000s."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph indicates that ordinary imports were greater than both types of processing imports in 2006, not that processing imports with inputs were greater than ordinary imports and processing imports with assembly that year. Choice C is incorrect because the observation that ordinary imports were greater than both types of processing imports in 2000, 2003, and 2006 doesn’t address a change within any type of imports from 2000 to 2006, and an indication of a change in that period that might be related to the availability of assets is needed to support the assertion that the situation of having limited capital resolved during the 2000s. Choice D is incorrect because the fact that processing imports with assembly were greater at the end of the period from 2000 to 2006 than processing imports with inputs were at the start of the same period doesn’t address a change within either type of imports during the period, and an indication of such a change that might be related to the availability of assets is needed to support the assertion that the situation of having limited capital resolved during the 2000s."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of Kristin Laidre’s reasoning about the purpose of the tusk that many, but not all, narwhals have. The text explains that one group of scientists thinks the tusk may help narwhals detect the threat of freezing water and that Laidre disagrees with that idea, given the importance of avoiding a dangerous situation. It’s logical to suggest that if the tusk serves such an important purpose for narwhals, the trait would be more common among them—specifically, that more narwhals would have a tusk."}, {"type": "paragraph", "text": "Choice A is incorrect because there’s no reason to think Laidre would say that if the tusk has the important function of helping narwhals detect when the water around them is about to freeze (meaning that it isn’t always freezing), some narwhals would choose a different habitat altogether. Indeed, if it’s true that the tusk helps narwhals avoid areas with dangerous conditions when they occur in their Arctic Ocean habitat, the tusk would likely enable the narwhals to continue living in that habitat rather than drive them elsewhere entirely. Choice B is incorrect because the text focuses only on narwhals and makes no mention of other marine animals or how having a tusk might affect them. And if anything, it would be more logical to expect a very important trait to be more widespread, not less common, among other similar types of animals. Choice D is incorrect. Although the text describes narwhals as shy, it doesn’t indicate that the scientists’ conclusion has anything to do with shyness. And because shyness and detection of the threat of freezing water aren’t logically connected, there’s no reason to think that Laidre would expect narwhals to become less shy over time if the tusk serves that important purpose."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of silicon carbide (SiC) fibers and creep, or deformation related to ongoing mechanical stress and elevated temperatures. The text states that Bhatt et al. found that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did. Because having a lower creep rate means that the material is slower to deform with exposure to stress, as the text explains, this finding suggests that aerospace composites made with the nitrogen-treated SiC fiber may be able to withstand mechanical stress for a longer period than those made with the other two polymer-derived SiC fibers can."}, {"type": "paragraph", "text": "Choice A is incorrect because it overstates the implications of the study’s findings, which have to do with the rate of a material’s deformation under stress, not the absolute degree of deformation. The text states that Bhatt et al. observed that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did, meaning only that it deformed more slowly over time under constant stress, not that it underwent less deformation overall."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t establish any similarity between the two polymer-derived SiC fibers other than that both had a higher creep rate than the nitrogen-treated SiC fiber did in Bhatt et al.’s study. Moreover, reducing a material’s resistance to creep would mean that the material becomes more susceptible to deformation with exposure to stress and elevated temperatures, which would be expected to shorten rather than prolong the lifespan of machinery made with that material. Choice C is incorrect because the text suggests that the stability of aerospace equipment may be better improved by composites containing nitrogen-treated SiC fiber than by composites containing the two polymer-derived SiC fibers, not the other way around. The text indicates that Bhatt et al. observed that the nitrogen-treated SiC fiber had a lower minimum creep rate than the other two fibers did, meaning that it was slower to degrade under exposure to mechanical stress and elevated temperatures—suggesting that it may remain stable for longer periods."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The singular verb “describes” agrees in number with the singular subject “map.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the plural verb “describe” doesn’t agree in number with the singular subject “map.” Choice C is incorrect because the plural verb “have described” doesn’t agree in number with the singular subject “map.”"}, {"type": "paragraph", "text": "Choice D is incorrect because the plural verb “are describing” doesn’t agree in number with the singular subject “map.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of determiners in a sentence. The plural determiner “these” agrees in number with the plural noun “letters” that it modifies. This choice clearly indicates that the letters demonstrate Alcott’s business sense."}, {"type": "paragraph", "text": "Choice A is incorrect because the singular determiner “one” doesn’t agree in number with the plural noun “letters.” Choice B is incorrect because the singular determiner “that” doesn’t agree in number with the plural noun “letters.” Choice C is incorrect because the singular determiner “this” doesn’t agree in number with the plural noun “letters.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb “affected,” used in conjunction with the phrase “during this time,” correctly indicates that the dust storms occurred in the 1930s."}, {"type": "paragraph", "text": "Choice A is incorrect because the present progressive tense verb “are affecting” doesn’t indicate that the dust storms occurred in the 1930s. Choice B is incorrect because the future perfect tense verb “will have affected” doesn’t indicate that the dust storms occurred in the 1930s. Choice C is incorrect because the future tense verb “will affect” doesn’t indicate that the dust storms occurred in the 1930s."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and a coordinating conjunction (“but”) to join the first main clause (“Leibniz...century”) and the second main clause (“these ingenious...calculators”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Choice D is incorrect because joining the two main clauses in this way with the subordinating conjunction “that” results in an ungrammatical and illogical sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite past participle “characterized” is correctly used within a supplementary element that modifies the main clause “Zhang...shanshui,” defining qinglü shanshui and explaining some of its identifying traits."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Using the finite present perfect tense verb “has been characterized” creates a second main clause in the sentence, and the two main clauses can’t be joined in this way by only the comma before “a type.” Choice B is incorrect because it results in a comma splice. Using the finite future tense verb “will be characterized” creates a second main clause in the sentence, and the two main clauses can’t be joined in this way by only the comma before “a type.” Choice D is incorrect because it results in a comma splice. Using the finite present tense verb “is characterized” creates a second main clause in the sentence, and the two main clauses can’t be joined in this way by only the comma before “a type.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (“What…vapor”) and another (“With…point”)."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a run-on sentence. The sentences (“What…vapor” and “with…point”) are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction “and” can’t be used in this way to join sentences."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase “the Alaska Centennial Commission” the subject of the sentence and places it immediately after the modifying phrase “wanting…Purchase.” In doing so, this choice clearly establishes that the Alaska Centennial Commission—and not another noun in the sentence— wanted to celebrate the 100th anniversary of the Alaska Purchase."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase “a contest” immediately after the modifying phrase illogically suggests that the contest wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase “an award of $\\$300$” immediately after the modifying phrase illogically suggests that the award of $\\$300$ wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase “$\\$300$” immediately after the modifying phrase illogically suggests that the $\\$300$ wanted to celebrate the 100th anniversary of the Alaska Purchase."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to mark the boundary between the main clause (“Recently...supposed”) and the supplementary element (“a finding...Paleolithic”) that provides additional information about the implications of the Neronian tool discovery."}, {"type": "paragraph", "text": "Choice A is incorrect because a semicolon can’t be used in this way to join the main clause (“Recently...supposed”) and the supplementary element (“a finding... Paleolithic”). Choice B is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “a finding.” Choice C is incorrect because it results in a run-on sentence. The main clause (“Recently...supposed”) and the supplementary element (“a finding...Paleolithic”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Additionally” logically signals that guard cells’ role in regulating water loss is an additional function of these specialized plant cells that is separate from the function of regulating carbon dioxide intake."}, {"type": "paragraph", "text": "Choice B is incorrect because “previously” illogically signals that the activity described in this sentence occurs earlier in a chronological sequence of events than the regulation of carbon dioxide intake described in the previous sentence. Instead, regulating water loss is an additional function of guard cells that is separate from the function of regulating carbon dioxide intake. Choice C is incorrect because “in conclusion” illogically signals that the description of guard cells’ role in regulating water loss concludes or summarizes the information about guard cells provided in the previous sentences. Instead, regulating water loss is one of the two distinct functions of guard cells described in the text. Choice D is incorrect because “instead” illogically signals that the activity described in this sentence happens in place of the activity of regulating carbon dioxide intake described in the previous sentence. Rather, regulating water loss is an additional function of guard cells."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence identifies the type of scientist Chaudhuri is, noting that she is a sedimentologist."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence provides an example of a type of sedimentary rock; it doesn’t identify what type of scientist Chaudhuri is. Choice B is incorrect. The sentence indicates types of rock that some scientists study; it doesn’t identify what type of scientist Chaudhuri is. Choice C is incorrect. While the sentence states that some scientists study sedimentary rocks, it doesn’t identify Chaudhuri as this type of scientist."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence indicates where “Raymond’s Run” takes place, stating that it takes place in Harlem."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence identifies the book in which the story “Raymond’s Run” was published; it doesn’t indicate where the story takes place."}, {"type": "paragraph", "text": "Choice C is incorrect. The sentence indicates the point of view used in “Raymond’s Run”; it doesn’t indicate where the story takes place. Choice D is incorrect. The sentence identifies the author of “Raymond’s Run”; it doesn’t indicate where the story takes place."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence contrasts the two styles of tiles, noting that tiles in the arista style have designs stamped into them, whereas tiles in the majolica style have designs painted directly on them."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence indicates that the two styles of tile can be found in the same location; it doesn’t contrast the two styles of tile."}, {"type": "paragraph", "text": "Choice B is incorrect because the sentence indicates that the Royal Alcázar of Seville features tiles in both the majolica and arista styles; it doesn’t contrast the two styles of tile. Choice D is incorrect because the sentence indicates that the tilework of the Royal Alcázar of Seville includes tiles in the majolica style; it doesn’t contrast tiles in the majolica style with tiles in the arista style."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence contrasts the two songs, noting that “Poor Miner’s Farewell” is about coal miners in Kentucky, whereas “Bring Him Back Home” is about Nelson Mandela."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes a similarity between “Poor Miner’s Farewell” and “Bring Him Back Home”; it doesn’t contrast the two songs."}, {"type": "paragraph", "text": "Choice C is incorrect. While the sentence provides a description of the song “Bring Him Back Home,” it doesn’t mention “Poor Miner’s Farewell” or contrast the two songs. Choice D is incorrect. While the sentence provides a description of the song “Poor Miner’s Farewell,” it doesn’t mention “Bring Him Back Home” or contrast the two songs."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. Using a quotation from Stewart, the sentence challenges Thucydides’s explanation that the rise of Athens caused the conflict, suggesting that it was instead caused by a “clash of cultures.”"}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence uses a quotation, the quotation doesn’t challenge Thucydides’s explanation of the conflict. Choice B is incorrect. While the sentence mentions that Stewart challenged Thucydides’s explanation of the conflict, it doesn’t use a quotation to challenge Thucydides’s explanation: the quoted word “inevitable” is from Thucydides. Choice D is incorrect. While the sentence appears to refute Thucydides’s explanation, it does so in a way that misrepresents the information in the notes; Allison’s Thucydides trap theory is based on Thucydides’s explanation of the conflict. Thus, Allison’s theory affirms, rather than challenges, Thucydides’s explanation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence presents an overview of the study’s findings, noting that, for some of the languages (the examples of Spanish and Vietnamese are given in the notes), the number of syllables spoken per second varied, while the amount of information conveyed per second remained roughly constant across all 17 languages."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence describes one of the metrics the study assessed, it doesn’t present any of the study’s findings. Choice B is incorrect. While the sentence compares specific findings about two of the languages studied, it doesn’t provide an overview of the study’s findings across all 17 languages. Choice C is incorrect. The sentence compares specific findings about two of the languages studied; it doesn’t provide an overview of the study’s findings across all 17 languages. It also misrepresents the information from the notes about Spanish’s information rate."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of carte de visite photos. To “popularize” a technology is to allow it to be used and appreciated widely. The text explains that unlike the photos produced by earlier forms of photographic technology, carte de visite photos were inexpensive and could easily be obtained by “everyday people,” who enjoyed exchanging the images. Therefore, carte de visite photos helped popularize photography."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that instead of weakening the emerging technology of photography, carte de visite photos allowed it to be more widely accessed and enjoyed by people. Choice B is incorrect. The text establishes that large numbers of people enjoyed using carte de visite photos, so it can be inferred that these photos caused photography to be praised, or celebrated. However, it wouldn’t make sense to say that inanimate objects—in this case, photos—had praised photography; instead, carte de visite consumers themselves would have praised it. Choice D is incorrect because the text explains that rather than isolating photography, or limiting its availability, carte de visite technology made photography more widely accessible to people."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of painter Alma W. Thomas’s work. In this context, “influenced” means to have had an effect on something’s development. The text indicates that there is a connection between Thomas’s work and the flowers and trees in her home’s garden, giving the example of Thomas’s brushstrokes being inspired by light shining through the leaves of a tree in front of her house. This context conveys that Thomas’s work was influenced by the flowers and trees in the garden."}, {"type": "paragraph", "text": "Choice A is incorrect because the text conveys that Thomas drew inspiration for her work from the plants in her garden, which suggests that the flowers and trees contributed positively to her work, not that they “restricted,” or limited, her work."}, {"type": "paragraph", "text": "Choice B is incorrect because it wouldn’t make sense to suggest that flowers and trees in a garden could have “announced,” or made known, a painter’s work."}, {"type": "paragraph", "text": "Choice C is incorrect because the text conveys that Thomas drew inspiration for her work from the plants in her garden, which suggests that the flowers and trees contributed positively to her work, not that they were a distraction. Further, it’s not clear how an artist’s work could itself be “distracted.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of the conservationists’ efforts to increase Azores bullfinch’s numbers. In this context, “successful” means accomplishing a goal or purpose. According to the text, conservationists planted more than 500,000 native trees in an Azores bullfinch habitat in order to boost the bird’s population size. The text then indicates that the population size did indeed grow as a result of the planted trees. Thus, in this context, the conservationists’ approach of planting native trees was successful because it achieved the goal of increasing the bird’s population size."}, {"type": "paragraph", "text": "Choice A is incorrect because the text gives no indication that the conservationists’ approach of planting native trees to increase Azores bullfinch’s numbers was “amusing,” or comical or entertaining. Instead, the approach was seriously undertaken and ultimately accomplished. Choice B is incorrect because the text doesn’t address how much it cost to achieve the goal of planting native trees to increase Azores bullfinch’s numbers. The text indicates that the approach was beneficial and successful rather than “costly,” or expensive or harmful."}, {"type": "paragraph", "text": "Choice D is incorrect. According to the text, the conservationists’ approach of planting native trees to increase Azores bullfinch’s numbers was beneficial and successful rather than “disastrous,” or damaging or unsuccessful."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the duration of gamma ray burst GRB 230307A. In this context, “an oddity” is something that is odd or unusual. The text explains that the burst lasted for 200 seconds and that other bursts generated by neutron mergers have usually lasted fewer than 2 seconds. In other words, the duration of gamma ray burst GRB 230307A was unusual."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on a difference between the duration of gamma ray burst GRB 230307A and the typical duration of bursts caused by neutron mergers, not “a coincidence,” or a point of correspondence, between them; the text indicates that GRB 230307A lasted much longer than what is typical of other bursts. Choice B is incorrect. In this context, “a reprieve” would be either a temporary relief from something or a delay of a punishment, neither of which would make sense as something that the duration of a gamma ray burst could provide to the burst itself. Choice C is incorrect. Although it would make sense to refer to gamma ray burst GRB 230307A itself as “an incident,” or a thing that occurred, the missing word describes the duration of the burst, and it doesn’t make much sense to describe a length of time as an incident. Further, the sentence emphasizes that the burst’s duration was very unusual, not simply that the burst occurred."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Benjamin Franklin’s popularity in France. In this context, “esteem” means high regard. The text indicates that Franklin was very popular, or highly regarded, in France, where he sought the country’s support for the United States in its fight for independence, and indicates that his status helped him achieve his goal. The context therefore suggests that being held in high regard by the people likely helped Franklin convince France to help the United States."}, {"type": "paragraph", "text": "Choice A is incorrect because the text directly indicates that it was Franklin’s popularity that likely helped him convince France to help the United States, not his “thoughtfulness” (which in this context would mean either his careful reasoning and attention or his kind consideration of others’ needs). Choice C is incorrect because the text doesn’t suggest that there was any “controversy,” or dispute, about Franklin’s presence in France; instead, the text states that Franklin was very popular in France and directly indicates that this status likely helped him convince France to help the United States. Choice D is incorrect because the text directly indicates that it was Franklin’s popularity that likely helped him convince France to help the United States, not his “sincerity,” or his honesty."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The first sentence of the text establishes that scientists didn’t know much about the ocean floor in the 1950s. The second sentence, which is underlined, describes what many scientists thought at the time—that the ocean floor was mostly flat. The remainder of the text establishes that the ocean floor is far from flat, citing research conducted by Marie Tharp and Bruce Heezen. Thus, the purpose of the underlined sentence is to identify a scientific belief that Tharp and Heezen showed to be wrong."}, {"type": "paragraph", "text": "Choice B is incorrect. Although Tharp and Heezen’s work with sonar data in the Atlantic Ocean is mentioned later in the text, the underlined sentence doesn’t describe the design of their experiment. Instead, it identifies a belief held by scientists that Tharp and Heezen demonstrated to be wrong. Choice C is incorrect because the underlined sentence presents a belief held by many scientists in the 1950s; nowhere does the text mention a disagreement between Tharp and Heezen, whom the text describes as research partners working together to map the ocean floor. Choice D is incorrect because the underlined sentence doesn’t present data in support of a claim; instead, it presents a scientific belief that Tharp and Heezen’s work showed to be wrong."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined phrase in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it accurately describes the function of the underlined phrase in the text as a whole. According to the text, advertisers were reluctant to support television in its early days. The underlined phrase then indicates that this reluctance was partly due to the US’s involvement in World War II, which hindered television production. Thus, the underlined phrase identifies a specific reason behind some advertisers’ hesitance to support television."}, {"type": "paragraph", "text": "Choice A is incorrect. The text merely mentions that television was expected to be financed through advertising, as radio was at the time. Nothing in the text compares the origins of radio and television. Choice C is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not measures taken to convince advertisers to support television. Choice D is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not what types of television programming were popular."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the function of the underlined sentence in the text as a whole. The text discusses the Bayeux Tapestry, making the point that the workers who produced the huge tapestry in the eleventh century might not have ever produced a tapestry so large before. The text goes on to suggest that because of this lack of previous experience, the workers developed and refined the process of joining the tapestry’s panels over time as they worked. The last sentence of the text then provides an example of an observation that suggests the workers’ process changed: clear misalignment of the borders of the two panels the workers joined first and virtually invisible joins completed later. Thus, the underlined sentence serves to support an argument about the workers who produced the tapestry."}, {"type": "paragraph", "text": "Choice A is incorrect because the example given in the last sentence of the text has to do with how the panels of the Bayeux Tapestry were joined by the workers, not with what is depicted in those panels; the text never identifies any people or places depicted in the tapestry. Choice C is incorrect because the last sentence compares how early panels in the Bayeux Tapestry were joined with how later panels in the same tapestry were joined; it doesn’t make any comparison between the Bayeux Tapestry and other tapestries from the same time in France. Choice D is incorrect because the last sentence doesn’t address the location where the Bayeux Tapestry was created; the first sentence of the text presents it as a given that the tapestry was created in France, but nothing in the text indicates how that origin was determined."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would the author of Text 2 most likely respond to what “some researchers contend” as described in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it reflects how the author of Text 2 would most likely respond to what the researchers mentioned in Text 1 contend. Text 1 discusses the lack of knowledge of how plate tectonics on Earth began. Text 1 also mentions researchers who contend that movements of tectonic plates began around 3 billion years ago. As support for this assertion, these researchers cite computer models (which are simulations, not empirical evidence) of the temperature in Earth’s mantle that show that at that time, the mantle would have been sufficiently molten for plates to move. However, the author of Text 2 asserts that empirical evidence from the geological record is necessary to make plausible claims about when tectonic movement began. Text 2 mentions an analysis performed by Wriju Chowdhury and his team of the geochemistry of zircon crystals (which would constitute empirical evidence). Chowdhury and his team argue, based on this analysis, that tectonic plates may have begun to move as early as 4.2 billion years ago. Therefore, since the author of Text 2 would consider Chowdhury et al.’s empirical evidence to be more conclusive than the computer models cited in Text 1, the author of Text 2 would most likely assert that a more definitive form of evidence than the computer models suggests a different timeline for the onset of plate tectonics on Earth."}, {"type": "paragraph", "text": "Choice A is incorrect because the author of Text 2 makes no claims about the temperature of Earth’s mantle and therefore wouldn’t argue that the temperature of Earth’s mantle 3 billion years ago was insufficient to allow tectonic movement."}, {"type": "paragraph", "text": "Choice B is incorrect because the author of Text 2 claims that empirical evidence is needed to fix the earliest date of tectonic movement. Computer models are simulations, not empirical evidence, so the author of Text 2 wouldn’t distinguish between different kinds of computer models but would instead argue that no computer models can reliably predict the onset of plate tectonics. Choice C is incorrect because the author of Text 2 wouldn’t consider any computer model to be able to provide evidence to support a plausible claim about tectonic movement, no matter how much such models were improved. The author of Text 2 would only accept empirical evidence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "What feature of Hevea brasiliensis does the text say is helpful for the process of making rubber?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately states what feature of Hevea brasiliensis is helpful for the process of making rubber. According to the text, this tree species produces latex, which is used to make rubber, and its inner bark contains a “network of tubes” that, when cut, enables the latex to flow out. The text explicitly states that this feature of Hevea brasiliensis is “helpful for the process of making rubber.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t mention the quality of the rubber produced from the latex of Hevea brasiliensis or compare its quality to that of rubber produced from other sources. Choice C is incorrect because the text never discusses the climates in which Hevea brasiliensis grows. Moreover, the text mentions only one region where this tree is found: the Amazon rainforest."}, {"type": "paragraph", "text": "Choice D is incorrect. Because the text states that Hevea brasiliensis is the world’s “main source of natural rubber,” it can be inferred that there is at least one other source. However, the text doesn’t specify whether that other source is also a tree species and, if so, whether that species grows in the Amazon rainforest."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it best states the main idea of the text: that nature-based approaches can be effective for achieving conservation goals. The text indicates that in many cases where conservationists are trying to protect ecosystems, their methods depend on natural processes or features. The text then gives an example of this phenomenon, a project with the Quinault Indian Nation that allowed logjams to form naturally in a river, creating spawning habitats for blueback salmon."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text does suggest that the partnership with the Quinault Indian Nation was beneficial, this is not the central aim of the text; the text primarily argues that nature-based approaches to conservation can be effective. Choice C is incorrect. Although the text indicates that logjams are helpful to blueback salmon, the example of the blueback salmon project is included to illustrate the larger point made earlier in the text: that nature-based approaches to conservation are often effective. Choice D is incorrect. There is no evidence in the text to support a direct comparison of the efficacy of nature- based conservation approaches to other types of approaches. The text merely indicates that nature-based approaches can often be effective."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the student’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it effectively uses data from the table to complete the student’s claim about the highest percentage of bus stops with shaded shelter in the areas represented. The table shows the highest average surface temperature of five areas and the percentage of bus stops with shaded shelter in each area, and 29% is the highest percentage listed."}, {"type": "paragraph", "text": "Choice A is incorrect because the list of percentages of bus stops with shaded shelter does not include 50%; the highest percentage in the table is 29%."}, {"type": "paragraph", "text": "Choice B is incorrect because 15% is the lowest value in the listed percentages of bus stops with shaded shelter, not the highest value. Choice C is incorrect because the list of percentages of bus stops with shaded shelter does not include 90%; the highest percentage in the table is 29%."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the table, what is the total area of Bahrain?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it states the total area of Bahrain that is indicated in the table. The table presents the total area (in square miles) and population for Bahrain, Qatar, and Kuwait, and it indicates that the total area of Bahrain is 304 square miles."}, {"type": "paragraph", "text": "Choice A is incorrect because the table indicates that 4,268,873 is the population of Kuwait, not the total area of Bahrain. Choice B is incorrect because the table indicates that 4,471 square miles is the total area of Qatar, not of Bahrain."}, {"type": "paragraph", "text": "Choice D is incorrect because the table indicates that 6,880 square miles is the total area of Kuwait, not of Bahrain."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which quotation from an article about Echelman’s sculptures, if true, would most effectively illustrate the underlined claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents the quotation that most effectively illustrates the claim that Echelman’s sculptures appear delicate but are in fact quite durable. The text explains that Echelman’s sculptures include flowing shapes that mimic the wind. If it is true that the materials she uses are both flexible and strong, that would help explain why the works are durable even though they appear delicate."}, {"type": "paragraph", "text": "Choice A is incorrect because the claim in the text is not about how Echelman models her work before sculpting. Choice B is incorrect because the claim in the text is not about the planning and design phases of Echelman’s work. Choice D is incorrect because the claim in the text is not about how the sculptures relate to their locations."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the researchers’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would most directly support the researchers’ conclusion that the transition from a stagnant lid regime to a tectonic plate regime occurred around 3.2 billion years ago. The text explains that early in Earth’s history, Earth exhibited a stagnant lid regime in which there’s no interaction between the lithosphere and the underlying mantle. The text further explains that, by contrast, once Earth began to exhibit a tectonic plate regime, its lithospheric and mantle material began to mix. If mantle-derived rocks younger than 3.2 billion years contain material not found in older mantle-derived rocks, that material must have originated somewhere other than the mantle. And if this material is found in both older and contemporaneous lithospheric rocks, that would imply that the lithosphere was able to mix with mantle material beginning around 3.2 billion years ago, as the researchers concluded."}, {"type": "paragraph", "text": "Choice A is incorrect. The text gives no basis for comparing the quantities of lithospheric and mantle-derived rocks. Choice B is incorrect. The text gives no basis for comparing the material makeup of lithospheric rocks to that of mantle- derived rocks. Choice C is incorrect. A positive correlation between the age of lithospheric rocks and these rocks’ chemical similarity to mantle-derived rocks would mean that the oldest rocks would be the most similar, which contradicts the text’s claim that lithospheric and mantle-derived rocks were completely separate until 3.2 billion years ago. If the researchers’ conclusion about the onset of tectonics on Earth is correct, then younger lithospheric rocks would show greater chemical similarity to mantle-derived rocks than older lithospheric rocks do."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the discussion of Uto-Aztecan languages. The text explains that the northern and southern branches of the Uto-Aztecan language family descended from a single language (believed to have originated in what is now the US Southwest), resulting in similarities across the family’s languages; however, the branches don’t have similar vocabulary for maize, even though maize has been cultivated by all Uto-Aztecan tribes. The text also indicates that maize originated in Mexico and spread northward into what is now the US Southwest—the area where the Uto-Aztecan language family originated. It follows, then, that the language family had already divided into northern and southern branches before maize reached that area; if maize had been present before the division occurred, the family’s origin language would have had terminology for it that likely would have been reflected in the branches, meaning they would have had similar vocabulary for maize. If maize arrived after the division occurred, however, the tribes in the two regions likely would have developed vocabulary pertaining to maize separately, at the times when they acquired the crop."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on vocabulary pertaining to maize in the branches of the Uto-Aztecan language family, and referring only to how some Uto-Aztecan tribes obtained maize wouldn’t directly address the role of language. Moreover, if northern Uto-Aztecan tribes had acquired maize from a southern Uto-Aztecan tribe, it’s reasonable to assume that the northern tribes might have also picked up southern Uto-Aztecan terminology for maize in that exchange. Choice B is incorrect because the text discusses the fact that the northern and southern branches of the Uto-Aztecan language family don’t have shared vocabulary pertaining to maize, not the idea that there are variations in such vocabulary within each branch—that is, the text focuses on differences between the two branches, not on differences between languages within a branch. Choice C is incorrect because the text focuses on vocabulary pertaining to maize in the branches of the Uto-Aztecan language family, and referring only to the timing and source of maize acquisition wouldn’t directly address the role of language. Furthermore, the text implies that southern Uto-Aztecan tribes probably acquired maize before the northern tribes did, given the evidence that maize originated in Mexico—the location of the best-known representative of the southern branch of the Uto-Aztecan language family—before spreading to the north."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of the sediments found at the Gale Crater’s Murray Formation on Mars. The text states that data gathered by the Curiosity rover suggest that bodies of water deposited sediment on Mars’s surface long ago. The text goes on to say that studying the sediment, Rivera-Hernández et al. found some coarse grains they believe are sandstone, which tends to be left by flowing water, and many more fine grains they believe are mudstone, which tends to slowly sink in low-flow water. The text further indicates that the researchers noted cracks in the fine grains that suggest there were cycles of desiccation, or drying, at the site. Taken together, this information suggests that a lake (a body of low-flow water) existed at the site for a prolonged period but occasionally experienced drying and that there were periods in which one or more streams (flowing water) were present, since the extended existence of a lake would account for the abundance of fine grains, periods of drying would account for the cracks in the fine grains, and periods with streams would account for the sections of coarse grains."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that an abundance of fine grains of sediment was found at the Murray Formation site, which suggests that a low-flow water source (such as a lake) was present. Further, the text makes no mention of where the water at the site may have originated from. Choice C is incorrect because the evidence described in the text doesn’t support the idea that there were streams at the Murray Formation for an extended period and a lake for just a short time. The abundance of fine grains suggests that a lake (a body of low-flow water) was present for an extended time, not just a short time, and the sections of coarse grains suggest that one or more streams (bodies of flowing water) were intermittently present while the lake existed, not at a separate time. Choice D is incorrect. Although the text suggests that both a low-flow body of water (such as a lake) and flowing water (such as streams) existed at the Murray Formation site, meaning that there could have been a stream-fed lake, the text explains that the fine grains that signify the presence of a lake exhibit cracking that indicates periods of desiccation, or drying, which suggests that a lake was present but did occasionally dry out."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Sidonian coins. As the text explains, researchers determined that Sidonian coins were made of silver and copper and that from 450 BCE to 367 BCE, the percentage of silver in each coin decreased from 98% to 74.2% while the percentage of copper increased from 1% to 24.7%. The text indicates that because the coins containing less than 80% silver weren’t considered suitable for trade (suggesting that copper was less valuable than silver) and looked different from coins containing more silver, the researchers suspect there was a serious loss in confidence in the currency in Sidon in 367 BCE when the copper content was high. It’s reasonable to assume that it wasn’t possible to boost confidence simply by devoting a greater amount of valuable silver to the currency, since Sidon was under significant and ongoing financial pressure; however, keeping the total amount of silver the same and reducing the amount of copper in the coins would have resulted in smaller coins with a higher percentage of silver. Therefore, it makes sense to suggest that Abd’aštart I (the ruler after 367 BCE) likely restored confidence in the currency by deciding to keep the amount of silver in Sidonian coins consistent with that in coins minted in 367 BCE but to decrease the coins’ weight."}, {"type": "paragraph", "text": "Choice A is incorrect because the text conveys that a crisis in confidence in the currency of Sidon likely occurred around 367 BCE because the percentage of silver in coins had fallen below 80% (presumably because Sidon’s financial pressures meant that less silver was available for currency), making the coins unsuitable for trade. Thus, announcing that the threshold for the percentage of silver in coins would be raised—that is, that coins would need to contain even more than 80% silver to be suitable for trade—likely would have worsened the crisis rather than relieved it. Choice C is incorrect because the text strongly suggests that a crisis in confidence in the currency of Sidon was caused by the proportion of silver to copper in the coins in 367 BCE, with 74.2% being too little silver for the coins to be considered suitable for trade; therefore, it’s unlikely that minting coins with a similar proportion of silver to copper (that is, still around 74.2% silver) would have restored confidence, even if the coins were heavier."}, {"type": "paragraph", "text": "Choice D is incorrect because the text gives no indication that funding the mining of more copper would have relieved a crisis in confidence in the currency of Sidon. The text establishes that Sidonian coins that visibly contained copper weren’t considered suitable for trade, so Abd’aštart I wouldn’t have wanted to add even more copper to them, and it’s unclear how else copper mining would affect views of the currency."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite to-infinitive verb “to include” is correctly used to form a subordinate clause that indicates what the Olympic committee decided (to include tug-of-war as an Olympic event)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in an ungrammatical sentence. The finite verb “included” can’t be used in this way to form a subordinate clause that indicates what the Olympic committee decided. Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle “including” can’t be used in this way to form a subordinate clause that indicates what the Olympic committee decided. Choice C is incorrect because it results in an ungrammatical sentence. The finite verb “include” can’t be used in this way to form a subordinate clause that indicates what the Olympic committee decided."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past tense verb “malfunctioned” is consistent with the other past tense verbs (“ignited” and “was”) used to describe the destruction of the original Globe Theatre."}, {"type": "paragraph", "text": "Choice A is incorrect because the present tense verb “malfunctions” isn’t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice B is incorrect because the future tense verb “will malfunction” isn’t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice C is incorrect because the present perfect tense verb “has malfunctioned” isn’t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use between a subject and a verb. No punctuation is needed when, as in this case, a subject (“Her portrait of novelist Zadie Smith”) is immediately followed by a main verb (“is displayed”)."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the subject and the verb. Choice B is incorrect because no punctuation is needed between the subject and the verb. Choice D is incorrect because no punctuation is needed between the subject and the verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun “it” agrees in number with the singular antecedent “industry” and clearly indicates that the industry consists of just one or two suppliers per municipality."}, {"type": "paragraph", "text": "Choice A is incorrect. The plural pronoun “these” neither agrees in number with the singular antecedent “industry” nor clearly indicates that the industry—not another plural noun in the sentence, such as “start-up costs” or “barriers”— consists of just one or two suppliers per municipality. Choice B is incorrect because the plural pronoun “they” doesn’t agree in number with the singular antecedent “industry.” Choice D is incorrect because the singular pronoun “this” is ambiguous in this context; the resulting sentence leaves unclear what consists of just one or two suppliers per municipality."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the punctuation of elements in a complex series. It’s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after “items” is conventionally used to separate the first item (“overseeing…items”) and the second item (“managing…law”) in a list of Hayden’s responsibilities."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Choice B is incorrect because a comma after “items” doesn’t match the semicolon used later to separate the second and third items in the series (“managing…law” and “and appointing the US poet laureate”). Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “Managing.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after “work” pairs with the comma after “though” to separate the supplementary element “though” from the rest of the sentence. This supplementary element signals that what follows is an exception to Chen using software tools to create illustrations, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence."}, {"type": "paragraph", "text": "Choice B is incorrect because the comma after “work” must be paired with a comma after “though” to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a semicolon can’t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a semicolon can’t be paired with a comma in this way to separate the supplementary element from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “though” from the preceding main clause (“They are hardly pristine”) and uses a semicolon to join the two main clauses (“They… though” and “many…objects”). Further, placing the semicolon after “though” indicates that the information in the preceding main clause (chondrites are far from pristine) is contrary to what might be assumed from the information in the previous sentence (chondrites have been generally unaltered by their environment)."}, {"type": "paragraph", "text": "Choice A is incorrect because placing the comma after “pristine” and using “though” as a subordinating conjunction illogically indicates that the information in the next main clause (many chondrites have experienced damage) is contrary to the information in the previous clause (chondrites are far from pristine)."}, {"type": "paragraph", "text": "Choice C is incorrect because placing the semicolon after “pristine” illogically indicates that the information in the next main clause (many chondrites have experienced damage) is contrary to the information in the previous clause (chondrites are far from pristine). Choice D is incorrect because it results in a comma splice. Without a conjunction following it, the comma after “though” can’t be used in this way to join two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (“That the...involved”) and the second main clause (“establishing...divisive”). Further, the semicolon is the most appropriate choice when joining two separate, parallel statements, such as here, where the information following the semicolon contrasts with the information before."}, {"type": "paragraph", "text": "Choice A is incorrect because placing a colon after “involved” illogically indicates that the information in the second main clause (the precise location was the subject of disagreement) explains or amplifies the information in the previous main clause (the general location was agreed upon by all). Instead, the information in the second clause contrasts with the previous information. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “As a result” logically signals that the action described in this sentence—closing the area around Garisenda Tower to explore stabilization solutions—occurred as a consequence or result of measurements revealing the tower’s concerning rotation."}, {"type": "paragraph", "text": "Choice A is incorrect because “similarly” illogically signals that the action of closing the tower area is similar to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation."}, {"type": "paragraph", "text": "Choice C is incorrect because “for example” illogically signals that the action of closing the tower area serves as an example of the tower’s concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation."}, {"type": "paragraph", "text": "Choice D is incorrect because “in comparison” illogically signals that the action of closing the tower area is being compared to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Specifically” logically signals that the information in this sentence—that the Local Bubble’s expansion trapped clouds of gas and dust that formed new stars—provides specific, precise details elaborating on the more general information in the previous sentence about the relationship between the Local Bubble’s expansion and the formation of new stars."}, {"type": "paragraph", "text": "Choice A is incorrect because “hence” illogically signals that the information in this sentence is a result of the information in the previous sentence about the relationship between the Local Bubble’s expansion and the formation of new stars. Instead, this sentence provides specific, precise details elaborating on that information. Choice B is incorrect because “however” illogically signals that the information in this sentence contrasts with the information in the previous sentence about the relationship between the Local Bubble’s expansion and the formation of new stars. Instead, this sentence provides specific, precise details elaborating on that information. Choice C is incorrect because “admittedly” illogically signals that the information in this sentence provides an exception or caveat to the previous information about the relationship between the Local Bubble’s expansion and the formation of new stars. Instead, this sentence provides specific, precise details elaborating on that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “In particular” logically signals that the information in this sentence—that maize and wheat supply chains transformed North American foodways into a global food system—provides specific, precise details elaborating on the more general information in the previous sentence about the transformation of North American foodways (with maize and wheat the “certain grains” at the center of it)."}, {"type": "paragraph", "text": "Choice B is incorrect because “alternatively” illogically signals that the information in this sentence is an alternative option to the previous information about the transformation of North American foodways. Instead, the roles of maize and wheat in creating a global food system are specific, precise details elaborating on that information. Choice C is incorrect because “by comparison” illogically signals that the information in this sentence is being compared to the previous information about the transformation of North American foodways. Instead, the roles of maize and wheat in creating a global food system are specific, precise details elaborating on that information. Choice D is incorrect because “second of all” illogically signals that the information in this sentence is a second, separate claim from the previous claim that North American foodways were transformed. Instead, the roles of maize and wheat in creating a global food system are specific, precise details elaborating on that information, rather than a separate claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “To that end” logically signals that the information in this sentence—the students’ creation of a show with six starring female roles—is the product of a goal or desire in the previous sentence (the students’ wish to develop a musical with roles for female actors)."}, {"type": "paragraph", "text": "Choice A is incorrect because “in other words” illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about the students’ wish to develop a musical with roles for female actors. Instead, the students’ show is the product of that desire. Choice B is incorrect because “in summary” illogically signals that the information in this sentence summarizes the previous information about the students’ wish to develop a musical with roles for female actors. Instead, the students’ show is the product of that desire. Choice C is incorrect because “for example” illogically signals that the information in this sentence is merely an example of the previous information about the students’ wish to develop a musical with roles for female actors. Instead, the students’ show is the direct product of that desire."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “More often” logically signals that the claim in this sentence—that new via ferratas favor recreation over utility—explains a difference between the new “sporting activity” routes and the older “mode of travel” routes. In so doing, it emphasizes and reinforces the previous claim (“modern via ferratas are rarely designed to simply reach a summit”)."}, {"type": "paragraph", "text": "Choice A is incorrect because “additionally” illogically signals that this sentence’s claim about new via ferratas adds a new, separate point to the previous claim (“modern via ferratas are rarely designed to simply reach a summit”). Instead, the second claim—that new routes favor recreation over utility—emphasizes and reinforces the previous one. Choice B is incorrect because “on the other hand” illogically signals that this sentence’s claim about new via ferratas contrasts with or opposes the previous claim (“modern via ferratas are rarely designed to simply reach a summit”). Instead, the second claim—that new routes favor recreation over utility—emphasizes and reinforces the previous one. Choice D is incorrect because “nonetheless” illogically signals that this sentence’s claim about new via ferratas is true despite the previous claim (“modern via ferratas are rarely designed to simply reach a summit”). Instead, the second claim—that new routes favor recreation over utility—emphasizes and reinforces the previous one."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence indicates the title of a novel that won a Nebula Award, noting that Babel-17 by Samuel Delany won the award in 1967."}, {"type": "paragraph", "text": "Choice B is incorrect because the sentence identifies the year that Samuel Delany published a science fiction novel; it doesn’t indicate the novel’s title or that it won a Nebula Award. Choice C is incorrect because the sentence provides an introduction of Samuel Delany; it doesn’t indicate the title of a novel that has won a Nebula Award. Choice D is incorrect because the sentence indicates that one of Samuel Delany’s novels met the qualification for a Nebula Award; it doesn’t indicate the novel’s title or that it won an award."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence indicates the year Yosemite Falls was completed, stating that it was completed in 1930."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence indicates where Obata created black ink paintings; it doesn’t indicate when the painting was completed. Choice B is incorrect. While the sentence identifies Obata as an artist who created a notable painting, it doesn’t indicate when that painting was completed. Choice D is incorrect. The sentence identifies the method Obata used; it doesn’t indicate when the painting was completed."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 7: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-7-math') then
    raise notice 'skipping sat-practice-test-7-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-7-math', 'SAT Practice Test 7: Math', 'Official SAT Practice Test 7 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 215, '[[200, 200], [210, 230], [210, 240], [210, 250], [210, 260], [210, 270], [210, 280], [230, 290], [250, 300], [260, 310], [280, 340], [300, 360], [320, 360], [330, 370], [340, 380], [350, 390], [360, 400], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [430, 470], [440, 480], [450, 490], [460, 500], [480, 520], [490, 530], [500, 540], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [580, 640], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [650, 710], [670, 730], [690, 750], [700, 760], [720, 770], [750, 780], [770, 800], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q01.png", "alt": "Figure for question 1", "width": 322}, {"type": "paragraph", "text": "The scatterplot shows the temperature, in degrees Fahrenheit ($^\\circ$F), and the distance above sea level, in feet, measured at $6$ locations on Mount Jefferson. A line of best fit is also shown."}, {"type": "paragraph", "text": "At a distance of $4{,}000$ feet above sea level, what is the temperature, in $^\\circ$F, predicted by the line of best fit?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At $x = 4{,}000$ the line of best fit is at about $35^\\circ$F."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Rectangle P has an area of $72$ square inches. If a rectangle with an area of $20$ square inches is removed from rectangle P, what is the area, in square inches, of the resulting figure?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$72 - 20 = 52$ square inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "|p| + 61 = 65"}, {"type": "paragraph", "text": "Which value is a solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$|p| = 4$, so $p = 4$ or $p = -4$. Only $4$ is listed."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Lorenzo purchased a box of cereal and some strawberries at the grocery store. Lorenzo paid $\\$2$ for the box of cereal and $\\$1.90$ per pound for the strawberries. If Lorenzo paid a total of $\\$9.60$ for the box of cereal and the strawberries, which of the following equations can be used to find $p$, the number of pounds of strawberries Lorenzo purchased? (Assume there is no sales tax.)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The strawberries cost $1.90p$ dollars and the cereal $2$ dollars, for a total of $9.60$: $1.90p + 2 = 9.60$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q05.png", "alt": "Figure for question 5", "width": 296}, {"type": "paragraph", "text": "The bar graph summarizes the charge, in kilowatt-hours (kWh), a battery received each day for $15$ days."}, {"type": "paragraph", "text": "For how many of these $15$ days did the battery receive a charge of $0$ kWh?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The bar above $0$ kWh reaches $6$ days."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A line in the $xy$-plane has a slope of $9$ and passes through the point $(0, -5)$. The equation $y = px + r$ defines the line, where $p$ and $r$ are constants. What is the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In $y = px + r$, $p$ is the slope, so $p = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['9']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is an $x$-coordinate of an $x$-intercept of the graph of $y = 3(x - 14)(x + 5)(x + 4)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$y = 0$ when $x = 14$, $x = -5$, or $x = -4$. Any of these is correct."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 7, 'spr', array['14', '-5', '-4']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q08.png", "alt": "Figure for question 8", "width": 322}, {"type": "paragraph", "text": "The graph shown gives the estimated value, in dollars, of a tablet as a function of the number of months since it was purchased. What is the best interpretation of the $y$-intercept of the graph in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $y$-intercept is at $0$ months, the time of purchase, where the value is about $\\$225$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangles $EFG$ and $JKL$ are congruent, where $E$, $F$, and $G$ correspond to $J$, $K$, and $L$, respectively. The measure of angle $E$ is $45^\\circ$ and the measure of angle $F$ is $20^\\circ$. What is the measure of angle $J$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $J$ corresponds to angle $E$, so it measures $45^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = \\dfrac{1}{2}(x + 6)$. What is the value of $f(4)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(4) = \\tfrac{1}{2}(10) = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q11.png", "alt": "Figure for question 11", "width": 254}, {"type": "paragraph", "text": "The graph of a system of an absolute value function and a linear function is shown. What is the solution $(x, y)$ to this system of two equations?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graphs intersect halfway between $x = -4$ and $x = -3$, at height halfway between $4$ and $5$: $\\left(-\\tfrac{7}{2}, \\tfrac{9}{2}\\right)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y = 6x + 3"}, {"type": "paragraph", "text": "One of the two equations in a system of linear equations is given. The system has infinitely many solutions. Which equation could be the second equation in this system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Infinitely many solutions means the second equation is the same line. Dividing $2y = 2(6x + 3)$ by $2$ gives $y = 6x + 3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $\\dfrac{6}{7}p + 18 = 54$, what is the value of $7p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\tfrac{6}{7}p = 36$, so $p = 42$ and $7p = 294$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['294']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 9x + 12 \\\\ x + 7y &= 20 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $x + 7(9x + 12) = 20$, so $64x = -64$ and $x = -1$. Then $y = 9(-1) + 12 = 3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 14, 'spr', array['3']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle in the $xy$-plane has the equation $(x - 13)^2 + (y - k)^2 = 64$. Which of the following gives the center of the circle and its radius?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$(x - h)^2 + (y - k)^2 = r^2$ has center $(h, k)$ and radius $r$. Here the center is $(13, k)$ and $r = \\sqrt{64} = 8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = |x - 4x|$. What value of $a$ satisfies $f(5) - f(a) = -15$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = |-3x| = 3|x|$, so $f(5) = 15$. Then $15 - f(a) = -15$ gives $f(a) = 30$, so $|a| = 10$. Only $10$ is listed."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For the exponential function $f$, the value of $f(0)$ is $c$, where $c$ is a constant. Of the following equations that define the function $f$, which equation shows the value of $c$ as the coefficient or the base?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In $f(x) = 33(1.5)^x$, $f(0) = 33(1) = 33$, which is the coefficient. (All four equations define the same function, with $f(0) = 33$.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(t) = 40{,}000(2)^{\\frac{t}{790}}$ gives the number of bacteria in a population $t$ minutes after an initial observation. How much time, in minutes, does it take for the number of bacteria in the population to double?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The base $2$ is raised to $\\tfrac{t}{790}$, so the population doubles each time $t$ increases by $790$ minutes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\frac{12}{n} - \\frac{2}{t} = -\\frac{2}{w}"}, {"type": "paragraph", "text": "The given equation relates the variables $n$, $t$, and $w$, where $n > 0$, $t > 0$, and $w > t$. Which expression is equivalent to $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{12}{n} = \\dfrac{2}{t} - \\dfrac{2}{w} = \\dfrac{2(w - t)}{tw}$, so $n = \\dfrac{12tw}{2(w - t)} = \\dfrac{6tw}{w - t}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q20.png", "alt": "Figure for question 20", "width": 327}, {"type": "paragraph", "text": "During a study, the temperature, in degrees Celsius ($^\\circ$C), of the air in a chamber was recorded to the nearest integer at certain times. The scatterplot shows the recorded temperature $y$, in $^\\circ$C, of the air in the chamber $x$ minutes after the start of the study."}, {"type": "paragraph", "text": "What was the average rate of change, in $^\\circ$C per minute, of the recorded temperature of the air in the chamber from $x = 5$ to $x = 7$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At $x = 5$ the temperature is $14$ and at $x = 7$ it is $24$: $\\dfrac{24 - 14}{7 - 5} = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 20, 'spr', array['5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In August, a car dealer completed $15$ more than $3$ times the number of sales the car dealer completed in September. In August and September, the car dealer completed $363$ sales. How many sales did the car dealer complete in September?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "If September had $s$ sales, August had $3s + 15$: $s + 3s + 15 = 363$, so $4s = 348$ and $s = 87$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 21, 'spr', array['87']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Points $Q$ and $R$ lie on a circle with center $P$. The radius of this circle is $9$ inches. Triangle $PQR$ has a perimeter of $31$ inches. What is the length, in inches, of $\\overline{QR}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$PQ$ and $PR$ are radii, $9$ inches each, so $QR = 31 - 18 = 13$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In a set of four consecutive odd integers, where the integers are ordered from least to greatest, the first integer is represented by $x$. The product of $12$ and the fourth odd integer is at most $26$ less than the sum of the first and third odd integers. Which inequality represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The odd integers are $x$, $x + 2$, $x + 4$, $x + 6$. \"At most $26$ less than the sum of the first and third\" is $\\le x + (x + 4) - 26$, and the product of $12$ and the fourth is $12(x + 6)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$y$"], "rows": [["$-2s$", "$24$"], ["$-s$", "$21$"], ["$s$", "$15$"]]}, {"type": "paragraph", "text": "The table shows three values of $x$ and their corresponding values of $y$, where $s$ is a constant. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slope is $\\dfrac{21 - 24}{-s - (-2s)} = -\\dfrac{3}{s}$. Using $(s, 15)$: $15 = -3 + b$, so $b = 18$ and $y = -\\dfrac{3}{s}x + 18$. Multiply by $s$: $sy = -3x + 18s$, or $3x + sy = 18s$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following expressions is equivalent to $(\\sin 24^\\circ)(\\cos 66^\\circ) + (\\cos 24^\\circ)(\\sin 66^\\circ)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$24^\\circ$ and $66^\\circ$ are complementary, so $\\sin 24^\\circ = \\cos 66^\\circ$ and $\\sin 66^\\circ = \\cos 24^\\circ$. The expression becomes $(\\cos 66^\\circ)^2 + (\\cos 24^\\circ)^2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The cost of renting a carpet cleaner is $\\$52$ for the first day and $\\$26$ for each additional day. Which of the following functions gives the cost $C(d)$, in dollars, of renting the carpet cleaner for $d$ days, where $d$ is a positive integer?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$C(d) = 52 + 26(d - 1) = 26d + 26$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = (x - 2)(x + 15)"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. For what value of $x$ does $f(x)$ reach its minimum?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The zeros are $2$ and $-15$. The parabola opens upward, so the minimum is halfway between them: $x = \\dfrac{2 + (-15)}{2} = -\\dfrac{13}{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['-13/2', '-6.5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A total of $165$ people contributed to a charity event as either a donor or a volunteer. $130$ people contributed as a donor. How many people contributed as a volunteer?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$165 - 130 = 35$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "There are $250$ trees in a park. Of these trees, $6\\%$ are birch trees. How many birch trees are in the park?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.06 \\times 250 = 15$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m2-q03.png", "alt": "Figure for question 3", "width": 267}, {"type": "paragraph", "text": "The graph of the quadratic function $y = f(x)$ is shown. What is the vertex of the graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The lowest point of the parabola is at $(0, 2)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The number of raccoons in a $131$-square-mile area is estimated to be $2{,}358$. What is the estimated population density, in raccoons per square mile, of this area?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$2{,}358 \\div 131 = 18$ raccoons per square mile."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "-11, -9, 26"}, {"type": "paragraph", "text": "A data set of three numbers is shown. If a number from this data set is selected at random, what is the probability of selecting a positive number?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Only $26$ is positive, so the probability is $\\tfrac{1}{3}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 45x + 600"}, {"type": "paragraph", "text": "The function $f$ gives the monthly fee $f(x)$, in dollars, a facility charges to keep $x$ crates in storage. What is the monthly fee, in dollars, the facility charges to keep $50$ crates in storage?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(50) = 45(50) + 600 = 2{,}850$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['2850']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 5\\left(\\dfrac{1}{4} - x\\right)^2 + \\dfrac{11}{4}$. What is the value of $f\\left(\\dfrac{1}{4}\\right)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f\\left(\\tfrac{1}{4}\\right) = 5(0)^2 + \\tfrac{11}{4} = \\tfrac{11}{4}$ (or $2.75$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 7, 'spr', array['11/4', '2.75']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $8x = 6$, what is the value of $72x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$72x = 9(8x) = 9(6) = 54$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $23x^3 + 2x^2 + 9x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor $x$ out of each term: $x(23x^2 + 2x + 9)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(9x^3 + 5x + 7) + (6x^3 + 5x^2 - 5)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Combine like terms: $15x^3 + 5x^2 + 5x + 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "At a state fair, attendees can win tokens that are worth a different number of points depending on the shape. One attendee won $S$ square tokens and $C$ circle tokens worth a total of $1{,}120$ points. The equation $80S + 90C = 1{,}120$ represents this situation. How many more points is a circle token worth than a square token?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A square token is worth $80$ points and a circle token $90$, so a circle token is worth $10$ more."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m2-q12.png", "alt": "Figure for question 12", "width": 256}, {"type": "paragraph", "text": "In the given scatterplot, a line of best fit for the data is shown."}, {"type": "paragraph", "text": "Which of the following is closest to the slope of the line of best fit shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line rises from about $y = 1.5$ at $x = 0$ to about $y = 14$ at $x = 7$, a slope of roughly $\\tfrac{12.5}{7} \\approx 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle has a radius of $2.1$ inches. The area of the circle is $b\\pi$ square inches, where $b$ is a constant. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Area $= \\pi r^2 = \\pi(2.1)^2 = 4.41\\pi$, so $b = 4.41$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 13, 'spr', array['4.41', '441/100']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $XYZ$, angle $Y$ is a right angle, point $P$ lies on $\\overline{XZ}$, and point $Q$ lies on $\\overline{YZ}$ such that $\\overline{PQ}$ is parallel to $\\overline{XY}$. If the measure of angle $XZY$ is $63^\\circ$, what is the measure, in degrees, of angle $XPQ$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $X = 180 - 90 - 63 = 27^\\circ$. Since $\\overline{PQ} \\parallel \\overline{XY}$, angle $ZPQ$ equals angle $ZXY = 27^\\circ$, so angle $XPQ = 180 - 27 = 153^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 14, 'spr', array['153']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An investment account was opened with an initial value of $\\$890$. The value of the account doubled every $10$ years. Which equation represents the value of the account $M(t)$, in dollars, $t$ years after the account was opened?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Doubling every $10$ years means a factor of $2$ for each $10$ years: $M(t) = 890(2)^{t/10}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &< x \\\\ x &< 22 \\end{aligned}"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given system of inequalities?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Every pair needs $y < x$ and $x < 22$. In table A each $y$ is one less than $x$ and every $x$ is below $22$. Tables C and D have $x > 22$, and B has $y > x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $\\dfrac{h^{15}q^7}{h^5q^{21}}$, where $h > 0$ and $q > 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract exponents: $h^{15-5} = h^{10}$ and $q^{7-21} = q^{-14}$, giving $\\dfrac{h^{10}}{q^{14}}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 3y &= 4x + 17 \\\\ -3y &= 9x - 23 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $39x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the equations: $0 = 13x - 6$, so $13x = 6$ and $39x = 18$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "h(t) = -16t^2 + b"}, {"type": "paragraph", "text": "The function $h$ estimates an object''s height, in feet, above the ground $t$ seconds after the object is dropped, where $b$ is a constant. The function estimates that the object is $3{,}364$ feet above the ground when it is dropped at $t = 0$. Approximately how many seconds after being dropped does the function estimate the object will hit the ground?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(0) = b = 3{,}364$. The object hits the ground when $16t^2 = 3{,}364$: $t^2 = 210.25$, so $t = 14.5$ seconds."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "2x^2 - 8x - 7 = 0"}, {"type": "paragraph", "text": "One solution to the given equation can be written as $\\dfrac{8 - \\sqrt{k}}{4}$, where $k$ is a constant. What is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "By the quadratic formula, $x = \\dfrac{8 \\pm \\sqrt{64 - 4(2)(-7)}}{2(2)} = \\dfrac{8 \\pm \\sqrt{120}}{4}$, so $k = 120$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 20, 'spr', array['120']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m2-q21.png", "alt": "Figure for question 21", "width": 328}, {"type": "paragraph", "text": "A line intersects two parallel lines, forming four acute angles and four obtuse angles. The measure of one of the acute angles is $(9x - 560)^\\circ$. The sum of the measures of one of the acute angles and three of the obtuse angles is $(-18x + w)^\\circ$. What is the value of $w$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "All acute angles are equal and each obtuse angle is $180 - (9x - 560)$. The sum is $(9x - 560) + 3(740 - 9x) = 1{,}660 - 18x$, so $w = 1{,}660$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 21, 'spr', array['1660']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$f(x)$"], "rows": [["$-4$", "$0$"], ["$-\\dfrac{19}{5}$", "$1$"], ["$-\\dfrac{18}{5}$", "$2$"]]}, {"type": "paragraph", "text": "For the linear function $f$, the table shows three values of $x$ and their corresponding values of $f(x)$. If $h(x) = f(x) - 13$, which equation defines $h$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f$ rises $1$ for every $\\tfrac{1}{5}$ increase in $x$, a slope of $5$, and $f(-4) = 0$, so $f(x) = 5x + 20$. Then $h(x) = 5x + 7$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The linear function $g$ is defined by $g(x) = b - 15x$, where $b$ is a constant. If $g(c + 7) = \\dfrac{c}{4}$, where $c$ is a constant, which of the following expressions represents the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$b - 15(c + 7) = \\tfrac{c}{4}$, so $b = \\tfrac{c}{4} + 15c + 105 = \\tfrac{61c}{4} + 105$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $XYZ$, angle $Z$ is a right angle and the length of $\\overline{YZ}$ is $24$ units. If $\\tan X = \\dfrac{12}{35}$, what is the perimeter, in units, of triangle $XYZ$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\tan X = \\dfrac{YZ}{XZ} = \\dfrac{12}{35}$, so $XZ = 70$. The hypotenuse is $\\sqrt{24^2 + 70^2} = 74$, and the perimeter is $24 + 70 + 74 = 168$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x^2 + 14x + y^2 = 6y + 109"}, {"type": "paragraph", "text": "In the $xy$-plane, the graph of the given equation is a circle. What is the length of the circle''s radius?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Complete the squares: $(x + 7)^2 + (y - 3)^2 = 109 + 49 + 9 = 167$, so the radius is $\\sqrt{167}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The speed of a vehicle is increasing at a rate of $7.3$ meters per second squared. What is this rate, in **miles per minute squared**, rounded to the nearest tenth? (Use $1$ mile $= 1{,}609$ meters.)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$7.3 \\dfrac{\\text{m}}{\\text{s}^2} \\times \\dfrac{(60\\text{ s})^2}{1\\text{ min}^2} \\times \\dfrac{1\\text{ mi}}{1{,}609\\text{ m}} = \\dfrac{7.3 \\times 3{,}600}{1{,}609} \\approx 16.3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= -2.5 \\\\ y &= x^2 + 8x + k \\end{aligned}"}, {"type": "paragraph", "text": "In the given system of equations, $k$ is a positive integer constant. The system has no real solutions. What is the least possible value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Set equal: $x^2 + 8x + k + 2.5 = 0$. No real solutions requires $64 - 4(k + 2.5) < 0$, so $k > 13.5$. The least integer is $14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['14']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;
