    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 1);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from John Muir’s 1913 autobiography The Story of My Boyhood and Youth. Muir describes being on a boat."}, {"type": "paragraph", "text": "The water was so clear that it was almost invisible, and when we floated slowly out over the plants and fishes, we seemed to be miraculously sustained in the air while exploring a veritable fairyland."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
