    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Angana Chaudhuri is a scientist.", "Chaudhuri studies sedimentary rocks.", "A scientist who studies sedimentary rocks is called a sedimentologist.", "Shale, chalk, and sandstone are examples of sedimentary rocks."]}, {"type": "paragraph", "text": "The student wants to identify what type of scientist Chaudhuri is."}]}'::jsonb, 'source') returning id into v_stim;
