    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["“Raymond’s Run” is a short story.", "It was written by African American author Toni Cade Bambara.", "It was first published in her book Gorilla, My Love in 1972.", "It is told from a first person perspective.", "It takes place in Harlem."]}, {"type": "paragraph", "text": "The student wants to indicate where the short story takes place."}]}'::jsonb, 'source') returning id into v_stim;
