    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 29);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The Royal Alcázar of Seville is a historic royal palace in Andalucía, Spain.", "The palace is famous for its intricate tilework.", "The palace features majolica and arista tiles.", "In the majolica style, designs are painted directly on the ceramic tiles.", "In the arista style, designs are stamped into the ceramic tiles."]}, {"type": "paragraph", "text": "The student wants to contrast the two styles of tiles."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Tiles in the majolica and arista styles can be found in the Royal Alcázar of Seville in Andalucía, Spain."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Featuring tiles in the majolica and arista styles, the Royal Alcázar of Seville in Spain is famous for its intricate tilework."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "In the arista style, designs are stamped into the ceramic tiles, whereas in the majolica style, the designs are painted directly on them."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Among the famous tilework of the Royal Alcázar of Seville are majolica style tiles, made by painting designs directly on the ceramic tiles."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 30);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Musicians around the world have used protest songs to raise awareness about human rights violations.", "US folk singer Aunt Molly Jackson released the protest song “Poor Miner’s Farewell” in 1932.", "It exposed the unlivable wages and dangerous working conditions coal miners faced in Kentucky during the 1920s and 1930s.", "South African singer-songwriter Hugh Masekela released the protest song “Bring Him Back Home” in 1987.", "It called on the South African government to free Nelson Mandela, an anti-apartheid leader who’d been unjustly imprisoned."]}, {"type": "paragraph", "text": "The student wants to contrast the song “Poor Miner’s Farewell” with the song “Bring Him Back Home.”"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The songs “Poor Miner’s Farewell” and “Bring Him Back Home” both raised awareness about human rights violations."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "While both are protest songs, “Poor Miner’s Farewell” is about coal miners in Kentucky, whereas “Bring Him Back Home” is about the anti-apartheid leader Nelson Mandela."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Hugh Masekela’s song “Bring Him Back Home,” released in 1987, called on the South African government to free Nelson Mandela."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Released in 1932 by Aunt Molly Jackson, the song “Poor Miner’s Farewell” was a protest against the unlivable wages and dangerous working conditions faced by Kentucky coal miners."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 31);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Political scientist Graham Allison is known for his Thucydides trap theory.", "Allison’s theory states that whenever “a rising power is threatening to displace a ruling power,” conflict is likely.", "The theory is based on Thucydides’s explanation of the conflict between Athens and Sparta.", "Thucydides wrote that “the rise of Athens and the fear this instilled in Sparta” made conflict “inevitable.”", "History professor Edmund Stewart recently challenged the historical basis of the theory.", "Stewart claimed that Athens was not a rising power and that the rivals experienced a “clash of cultures” instead."]}, {"type": "paragraph", "text": "The student wants to use a quotation to challenge Thucydides’s explanation of the conflict between Athens and Sparta."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "According to Allison’s Thucydides trap theory, whenever “a rising power is threatening to displace a ruling power,” conflict is likely."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Thucydides wrote that conflict between the two powers was “inevitable,” although Stewart later challenged the historical basis of this claim."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "According to Stewart, a “clash of cultures” between Athens and Sparta caused the conflict, not Athens’s rise."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Thucydides explained that conflict was caused by “the rise of Athens and the fear this instilled in Sparta,” but Allison disagreed, seeing the conflict as an example of the Thucydides trap."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 32);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Researchers in a 2021 study wanted to determine the rate at which 17 languages conveyed both information and syllables.", "They calculated the bits of information conveyed per second (the IR, or information rate).", "The IR was found to be approximately consistent across the 17 languages (an average of 39 bits per second).", "They calculated the number of syllables spoken per second (the SR, or syllable rate).", "Spanish had the second-fastest SR (7.7 syllables per second).", "Vietnamese had the sixteenth-fastest SR (5.3 syllables per second)."]}, {"type": "paragraph", "text": "The student wants to present an overview of the study’s findings."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The 2021 study determined the information rate (IR) of 17 languages in bits of information conveyed per second."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Researchers found that information was conveyed more quickly in Spanish, at 7.7 syllables per second, than in Vietnamese, at 5.3 syllables per second."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Vietnamese had the sixteenth-fastest syllable rate, lower than that of Spanish, which had the second-fastest; however, Spanish had the lower information rate of the two."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Though some of the languages differed in number of syllables spoken per second, all 17 conveyed information at roughly the same rate."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 33);
    insert into public.exam_sections (exam_id, position, title) values (v_exam, 2, 'Module 2') returning id into v_section;
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Taking photographs in the mid-1800s was complicated and expensive, but this changed with the 1854 invention of the carte de visite, a small photo that cost little to make. Carte de visite photos helped to ______ photography: they made it easy and enjoyable for everyday people to have their pictures taken, and people at the time loved exchanging these small photos with friends and family."}]}'::jsonb, 'source') returning id into v_stim;
