    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "weaken"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "praise"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "popularize"}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "isolate"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 34);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Painter Alma W. Thomas was fascinated by the colors and shapes found in nature. The flowers and trees in the garden at her home in Washington, DC, ______ her work. For example, Thomas’s use of broken brushstrokes was inspired by the way that light would shine through the leaves of a tree in front of her house."}]}'::jsonb, 'source') returning id into v_stim;
